const input = $('Normalize CRM Writer Input').first().json;
const reference = $input.first().json || {};
const canonicalLeadId = Number(reference.canonical_lead_id || input.lead_id);

if (!canonicalLeadId || Number.isNaN(canonicalLeadId)) {
  throw new Error(
    `Could not resolve canonical lead_id. Incoming lead_id=${input.lead_id}, email=${input.lead_email}`
  );
}

function clean(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function limit(value, max = 1800) {
  const text = clean(value);
  return text.length > max ? text.slice(0, max) + "\n[TRUNCATED]" : text;
}

function normalizeCrmStatus(value) {
  const status = clean(value).toLowerCase();

  if (status === "qualified") return "Qualified";
  if (status === "nurture") return "Nurture";
  if (status === "disqualified") return "Disqualified";

  return "New";
}

function normalizePriority(value) {
  const cleanValue = clean(value);
  const allowed = ["Low", "Medium", "High", "Urgent"];
  return allowed.includes(cleanValue) ? cleanValue : "Medium";
}

function normalizeFit(value) {
  const cleanValue = clean(value);
  const allowed = ["Low", "Medium", "High"];
  return allowed.includes(cleanValue) ? cleanValue : "Low";
}

const leadScore = input.lead_score || {};
const enrichment = input.enrichment || {};

const leadTitle =
  clean(input.lead_name) ||
  clean(input.lead_email) ||
  clean(input.company_name) ||
  `Lead ${input.lead_id}`;

const crmNotes = [
  input.message ? `Lead message:\n${input.message}` : "",
  leadScore.reasoning_summary ? `\nScoring reasoning:\n${leadScore.reasoning_summary}` : "",
  leadScore.recommended_next_action ? `\nRecommended next action:\n${leadScore.recommended_next_action}` : "",
  leadScore.follow_up_angle ? `\nFollow-up angle:\n${leadScore.follow_up_angle}` : "",
  enrichment.intent?.detected_use_case ? `\nDetected use case:\n${enrichment.intent.detected_use_case}` : "",
  Array.isArray(enrichment.intent?.automation_pain_points) && enrichment.intent.automation_pain_points.length
    ? `\nAutomation pain points:\n- ${enrichment.intent.automation_pain_points.join("\n- ")}`
    : "",
  Array.isArray(leadScore.missing_information) && leadScore.missing_information.length
    ? `\nMissing information:\n- ${leadScore.missing_information.join("\n- ")}`
    : ""
].filter(Boolean).join("\n");

const crm = {
  crm_lead_page_id: reference.crm_lead_page_id || null,
  crm_action: reference.crm_lead_page_id ? "update" : "create",

  lead_title: leadTitle,
  lead_name: clean(input.lead_name),
  lead_email: clean(input.lead_email),
  lead_phone: clean(input.lead_phone),
  job_title: clean(input.job_title),

  company_name: clean(input.company_name),
  company_domain: clean(input.company_domain),
  website_url: clean(input.website_url),

  status: normalizeCrmStatus(leadScore.lead_status),
  priority: normalizePriority(leadScore.priority),
  fit_level: normalizeFit(leadScore.fit_level),
  lead_score: Number(leadScore.lead_score || 0),

  routing_team: clean(leadScore.routing_team),
  source: clean(input.event_source || input.lead_source),

  next_action: limit(leadScore.recommended_next_action, 500),
  notes: limit(crmNotes, 1900)
};

return [
  {
    json: {
      ...input,
      lead_id: canonicalLeadId,
      crm
    }
  }
];

const notion = $input.first().json || {};
const data = $('Build CRM Payload').first().json;

const crmLeadPageId =
  notion.id ||
  data.crm.crm_lead_page_id ||
  null;

if (!crmLeadPageId) {
  throw new Error("CRM write completed but no Notion page ID was returned.");
}

const crmSync = {
  crm_system: "Notion",
  crm_action: data.crm.crm_action,
  crm_lead_page_id: crmLeadPageId,
  crm_status: data.crm.status,
  crm_priority: data.crm.priority,
  crm_fit_level: data.crm.fit_level,
  crm_lead_score: data.crm.lead_score,
  synced_at: new Date().toISOString()
};

return [
  {
    json: {
      ...data,
      crm_sync: crmSync,
      crm_lead_page_id: crmLeadPageId
    }
  }
];
